WFJ.Data.add("spell", {
  [425012] = { "即座にオフハンド武器を投げて通常のオフハンド武器ダメージを与え、$N1%の確率でオフハンド武器の毒を対象に付与します。コンボポイントを$N2得ます。対象にかかっているDeadly Poison一回ごとにEnergyを$N3返還します。\n\nPoisoned KnifeはSinister Strikeで発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0xefa7ed2e, nil, "um" },
  [425013] = { "即座にオフハンド武器を投げて通常のオフハンド武器ダメージを与え、$N1%の確率でオフハンド武器の毒を対象に付与します。コンボポイントを$N2得ます。\n\nPoisoned KnifeはSinister Strikeで発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0x2e09c327, nil, "um" },
  [425067] = { "ゴブリン流に重い門を開けます！", nil, 0x13dc7dbc, nil, "um" },
  [425094] = { "BrotherとSisterのHalf-Keysを組み合わせます。", nil, 0x1df3c5ff, nil, "um" },
  [425102] = { "ベルトにPoisoned Knifeのルーンを刻みます：\n\n$I1\nオフハンド武器を即座に投げて通常のオフハンド武器ダメージを与え、100%の確率でオフハンド武器の毒を対象に付与します。コンボポイントを$N2獲得します。対象に付与されたDeadly Poisonごとに、Energyを$N3返還します。\n\nPoisoned Knifeは、Sinister Strikeから発動する、またはSinister Strikeを変化させるすべてのタレントと効果の恩恵を受けます。", nil, 0xdae3547b, nil, "um" },
  [425103] = { "ブーツにMaster of Subtletyのルーンを刻みます：\n\n$I1\n隠密中、および隠密を解除してから6秒間に行った攻撃のダメージが、さらに$N2%増加します。", nil, 0xb4456c3f, nil, "um" },
  [425121] = { "詠唱を加速させ、呪文の詠唱速度を$N1%上昇させ、詠唱中にダメージを伴う攻撃で受ける押し戻しを$N2%軽減します。効果時間は$D1です。", "すべての呪文の詠唱速度が$N1%上昇し、詠唱中にダメージ攻撃で受ける詠唱の遅れが$N2%減少しています。", 0xa582f7cd, 0xedaed79f, "uu" },
  [425124] = { "残りのmanaをすべて解き放ち、エネルギーの奔流として対象に集中させ、$N1のArcaneダメージを与えます。このダメージは残りのmanaに応じて最大$N2%増加します。その後、通常のmana回復が再開され、$D1の間$N3%増加します。", "通常のmana回復が有効になり、$N1%増加しています。", 0x339bcb87, 0xa28241d9, "uu" },
  [425170] = { "脚部にIcy Veinsのルーンを刻みます：\n\n$I1\n呪文の詠唱を加速し、詠唱速度を$N1%上昇させ、詠唱中にダメージを受けて生じる詠唱の遅延を$N2%軽減します。効果時間は$D1です。", nil, 0xe3b2f6e8, nil, "um" },
  [425171] = { "脚部にArcane Surgeのルーンを刻みます：\n\n$I1\n残りのmanaをすべて解き放ち、エネルギーの奔流として対象に集中させ、$N1のArcaneダメージを与えます。このダメージは残りのmanaに応じて最大$N2%増加します。その後、通常のmana回復が有効になり、$D1の間$N3%増加します。", nil, 0x5e00b891, nil, "um" },
  [425204] = { "対象を病に冒し、$D1かけて$N1のShadowダメージを与えます。", "$N2秒ごとに$N1のダメージを与えます。", 0x6d5d1c3a, 0xa713b2d8, "uu" },
  [425207] = { "$D1の間、指定した場所に聖なる障壁を呼び出してパーティメンバー全員を守り、受けるすべてのダメージを$N2%軽減し、ダメージによる詠唱の遅延を防ぎます。", nil, 0xb1dd5c90, nil, "um" },
  [425213] = { "手首にPower Word: Barrierのルーンを刻みます：\n\n$I1\n対象地点に聖なる障壁を$D1の間召喚してパーティーメンバー全員を守り、受けるダメージをすべて$N2%軽減し、ダメージによる詠唱の遅延を防ぎます。", nil, 0x192ed3ca, nil, "um" },
  [425215] = { "胸部か法衣にTwisted Faithのルーンを刻みます：\n\n$I1\nMind FlayとMind Blastが、自分のShadow Word: Painに冒されている対象に与えるダメージが$N1%増加します。", nil, 0x66bd1c0b, nil, "um" },
  [425216] = { "ブーツにVoid Plagueのルーンを刻みます：\n\n$I1\n対象を病気に冒し、$D1かけて$N1のShadowダメージを与えます。", nil, 0x42ee551e, nil, "um" },
  [425268] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425269] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425270] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425271] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425272] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425273] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425274] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425275] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425276] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425277] = { "$D1かけて対象のダメージを$N1回復します。", "$N2秒ごとに$N1のダメージを回復します。", 0x582e0822, 0x4b6eb5c1, "uu" },
  [425280] = { "Flash Heal、Binding Heal、Lesser Heal、Heal、Greater Heal、Penanceによる回復は、Weakened Soulがかかっている対象に唱えるとクリティカル率が$N1%上昇し、対象のWeakened Soulの残り効果時間を$N2秒短縮します。", nil, 0x1cb93a0f, nil, "um" },
  [425285] = { "エレメントの霊たちに呼びかけます。", nil, 0x091afdbb, nil, "um" },
  [425294] = { "純粋なShadowエネルギーに分散し、受けるすべてのダメージを$N1%軽減します。攻撃や呪文の詠唱はできませんが、$D2の間、$N3秒ごとにmanaを$N2%回復します。Dispersionはスタン、恐怖、沈黙状態でも使用でき、使用時にすべての移動速度低下効果と移動妨害効果を解除し、分散している間はそれらに対して無効になります。", "受けるすべてのダメージが$N1%軽減され、$D2の間、$N3秒ごとにmanaを$N2%回復しています。攻撃や呪文の詠唱はできません。移動速度低下効果と移動妨害効果に対して無効です。", 0xf9ae902a, 0xa58e8279, "uu" },
  [425309] = { "ベルトにEmpowered Renewのルーンを刻みます：\n\n$I1\nRenewが、付与された時に即座に一度追加で回復するようになり、回復するたびに回復量ボーナス効果から受ける恩恵が$N1%増加します。\n\nさらに、別のプリーストのRenewを受けている対象にもRenewを付与できるようになります。", nil, 0xe14c3cd2, nil, "um" },
  [425310] = { "ベルトにRenewed Hopeのルーンを刻みます：\n\n$I1\nFlash Heal、Binding Heal、Lesser Heal、Heal、Greater Heal、Penanceによる回復は、Weakened Soulを受けている対象に使用するとクリティカル率が$N1%上昇し、その対象のWeakened Soulの残り時間を$D1短縮します。", nil, 0x88a25871, nil, "um" },
  [425312] = { "ブーツにSpirit of the Redeemerのルーンを刻みます：\n\n$I1\n発動すると$D1の間Spirit of Redemptionになります。この姿の間はあらゆる回復呪文をコストなしで詠唱できますが、移動、攻撃はできず、攻撃されることも、呪文や効果の対象になることもありません。発動にはSpirit of Redemptionのタレントが必要で、死亡時にSpirit of Redemptionになることはなくなります。", nil, 0x10efc022, nil, "um" },
  [425314] = { "ブーツにDispersionのルーンを刻みます：\n\n$I1\n純粋なShadowエネルギーへと分散し、受けるダメージをすべて$N1%軽減します。攻撃も呪文の詠唱もできなくなりますが、$D2の間$D1ごとにmanaを$N2%回復します。Dispersionはスタン、恐怖、沈黙状態でも使用でき、使用時にすべての鈍足効果と移動妨害効果を解除し、分散中はそれらへの耐性を得ます。", nil, 0x0287aa9b, nil, "um" },
  [425336] = { "$D1の間、攻撃速度を$N1%増加させます。", "攻撃速度が$N1%増加しています。", 0x7e4b2c7f, 0x8859e2db, "uu" },
  [425339] = { "前方の円錐範囲にいる最大$N1体の敵に$N2のFireダメージを与えます。このアビリティは大量の脅威を発生させます。Flame Shockの持続ダメージには、$N3%の確率でMolten Blastのクールダウンをリセットする効果があります。", nil, 0x08546866, nil, "um" },
  [425343] = { "脚部にGreater Ghost Wolfのルーンを刻みます：\n\n$I1\nGhost Wolfが屋内でも使用できるようになり、発動中は受けるダメージをすべて$N1%軽減します。", nil, 0x0f11028d, nil, "um" },
  [425344] = { "手袋にMolten Blastのルーンを刻みます：\n\n$I1\n前方の円錐範囲内の最大$N1体の敵を爆破し、$N2のFireダメージを与えます。このアビリティは大量の脅威を生み出します。Flame Shockの持続ダメージは、$N3%の確率でMolten Blastのクールダウンをリセットします。", nil, 0x23c7149c, nil, "um" },
  [425443] = { "手袋にQuick Strikeのルーンを刻みます：\n\n$I1\n両手武器で無謀な即時近接攻撃を行い、$N1の物理ダメージを与えます。このアビリティはHeroic Strikeに関連するすべての効果の恩恵を受け、それらを発動させます。", nil, 0xfe2ebe8b, nil, "um" },
  [425444] = { "胸部にRaging Blowのルーンを刻みます：\n\n$I1\n武器ダメージの$N1%を与える猛烈な一撃ですが、Enrage、Berserker Rage、Bloodrageのいずれかが有効な間にしか使用できません。Enrage、Berserker Rage、Bloodrageのいずれかが有効な間に他の近接アビリティを使用するたびに、Raging Blowの残りクールダウンが$D1短縮されます。", nil, 0x95af0904, nil, "um" },
  [425445] = { "胸部にWarbringerのルーンを刻みます：\n\n$I1\nCharge、Intercept、Interveneが、戦闘中でもどの構えでも使用できるようになり、発動時にすべての移動妨害効果を解除します。", nil, 0xd9810bbd, nil, "um" },
  [425446] = { "脚部にConsumed by Rageのルーンを刻みます：\n\n$I1\nRageが$N2を超えると、$D1の間Enrage状態になります（Enraged状態が必要なアビリティが使用可能になります）。さらに、Enraged状態の間はWhirlwindがオフハンドの近接武器でも攻撃します。", nil, 0x002a5c3b, nil, "um" },
  [425447] = { "脚部にFrenzied Assaultのルーンを刻みます：\n\n$I1\n両手武器を装備している間、攻撃速度が$N2%上昇し、近接攻撃が命中するとRageを追加で$N3生み出します。クリティカルヒットの場合は追加で$N4生み出します。", nil, 0x17dbef85, nil, "um" },
  [425463] = { "フェルエネルギーをみなぎらせ、ペットと自分の回避率を$N1%、すべての攻撃のクリティカル率を$N2%上昇させます。効果時間は$D1です。", "回避率が$N1%上昇しています。\n主人のクリティカル率が$N2%上昇しています。", 0x95ecc1be, 0xb041bbc1, "uu" },
  [425464] = { "別の悪魔のペットを召喚しても、Demonic Sacrificeの効果が解除されなくなります。生贄にしたペットを再召喚すると、効果は解除されます。", nil, 0x910d423f, nil, "um" },
  [425476] = { "脚部にDemonic Pactのルーンを刻みます：\n\n$I1\nDemonic Sacrificeの効果が、別の悪魔のペットを召喚しても解除されなくなります。生け贄にしたペットを再召喚すると、効果は解除されます。", nil, 0x15896149, nil, "um" },
  [425477] = { "脚部にDemonic Graceのルーンを刻みます：\n\n$I1\nフェルエネルギーをみなぎらせ、ペットと自分の回避率を$N1%、すべての攻撃のクリティカル率を$N2%上昇させます。効果時間は$D1です。", nil, 0x08b6b628, nil, "um" },
  [425497] = { "餌を投げます。", nil, 0xb670e33c, nil, "um" },
  [425600] = { { "パラディンがHorn of Lordaeronを吹き鳴らし、$N1ヤード以内のパーティーメンバー全員のStrengthとAgilityの合計を$N2上昇させます。効果時間は$D1です。Blessing of Mightとは重複しません。", shape = { "3/1" } }, "StrengthとAgilityの合計が$N1増加します。", 0xc2588b8d, 0x4c95c821, "uu" },
  [425609] = { "呪文の詠唱を中断させ、$D1の間その系統の呪文を唱えられなくします。", nil, 0x25cb829f, nil, "um" },
  [425618] = { "胸部にHallowed Groundのルーンを刻みます：\n\n$I1\nConsecrationが、範囲内のパーティーメンバーをConsecrationのダメージ量の$N1%分回復するようになります。", nil, 0x96d0ec24, nil, "um" },
  [425619] = { "胸部にAegisのルーンを刻みます：\n\n$I1\nブロック値を$N1%上昇させ、Redoubtタレントを変化させます。Redoubtは、自分への近接攻撃または遠隔攻撃を受けた時にも$N2%の確率で発動するようになり、近接クリティカルを与えた時には必ず発動します。さらに、Reckoningタレントは、自分への近接攻撃または遠隔攻撃を受けた時に、タレントポイントごとに$N3%の確率で発動するようになります。", nil, 0x4ecc3126, nil, "um" },
  [425621] = { "脚部にRebukeのルーンを刻みます：\n\n$I1\n呪文の詠唱を中断させ、$D1の間その系統の呪文を詠唱できなくします。", nil, 0x69981c41, nil, "um" },
  [425711] = { "前方のすべての敵を近接武器で薙ぎ払い、武器ダメージの$N1%を与えます。主な対象が受けるダメージは$N2%増加します。", nil, 0x24f251b2, nil, "um" },
  [425728] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425729] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425730] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425732] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
