  [425734] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425735] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425736] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425737] = { "対象を刺し、$D1かけて$N1のNatureダメージを与えます。同じ対象にかけられるStingは、ハンターごとに1つだけです。", "$N2秒ごとに$N1のNatureダメージを与えます。", 0x7d1286a5, 0x549b2d67, "uu" },
  [425758] = { "手袋にCarveのルーンを刻みます：\n\n$I1\n前方のすべての敵を近接武器でなぎ払い、武器ダメージの$N1%を与えます。主目標が受けるダメージは$N2%増加します。", nil, 0x3c61f546, nil, "um" },
  [425759] = { "胸部か法衣にCobra Strikesのルーンを刻みます：\n\n$I1\nShotとStrikeのアビリティ、およびMongoose Biteでクリティカルヒットを与えると、ペットの次の2回の特殊攻撃が必ずクリティカルヒットになります。", nil, 0xd5359e71, nil, "um" },
  [425760] = { "脚部にSerpent Spreadのルーンを刻みます：\n\n$I1\nMulti-Shotが命中した対象は、$D1の間Serpent Stingにも冒されます。", nil, 0x5f415872, nil, "um" },
  [425762] = { "脚部にFlanking Strikeのルーンを刻みます：\n\n$I1\n自分とペットが同時に即時の近接攻撃を行い、$N1%の近接ダメージを与えます。その後、$D1の間与えるダメージが$N2%増加し、最大$N4回までスタックします。ペットのBasic攻撃は、$N5%の確率でFlanking Strikeのクールダウンをリセットします。", nil, 0x2cd65e38, nil, "um" },
  [425798] = { nil, "このユニットは最近Gurubashi Arenaの宝箱を略奪したため、しばらくの間は再び戦利品を得られません。", nil, 0x78eb8040, "mu" },
  [425874] = { "対象の足元にhealth $N2のDecoy Totemを$D1の間召喚し、対象への次の近接攻撃または遠隔攻撃をトーテムにそらします。トーテムは対象に$D2の間、移動阻害効果への耐性も与えます。", nil, 0x4df50519, nil, "um" },
  [425882] = { "ブーツにDecoy Totemのルーンを刻みます：\n\n$I1\n対象の足元に、healthが$N2のDecoy Totemを$D1の間召喚します。対象への次の近接攻撃または遠隔攻撃は、代わりにトーテムに向けられます。さらにトーテムは、$D2の間、対象に移動妨害効果への耐性を与えます。", nil, 0x8e83f725, nil, "um" },
  [425883] = { "ブーツにAncestral Awakeningのルーンを刻みます：\n\n$I1\nHealing WaveまたはLesser Healing Waveでクリティカル回復をすると、Ancestralの霊を召喚して助けを得ます。霊は40ヤード以内でhealthの割合が最も低いパーティーメンバーを、回復量の$N2%分即座に回復します。", nil, 0x93669494, nil, "um" },
  [425887] = { nil, "あなたの中の何かが、Gnollの血と復讐に飢えています……", nil, 0xc8c5dbf4, "mu" },
})
